<?php
namespace Database\Seeders; use App\Enums\UserRole; use Illuminate\Database\Seeder; use Spatie\Permission\Models\{Permission, Role};
class RolePermissionSeeder extends Seeder { public function run(): void { $permissions=['orders.view','orders.create','orders.assign','orders.progress','payments.manage','workers.manage','wallet.withdraw','affiliate.view','dashboard.view']; foreach($permissions as $permission) Permission::firstOrCreate(['name'=>$permission,'guard_name'=>'web']); $map=[UserRole::Owner->value=>$permissions, UserRole::Admin->value=>['orders.view','orders.assign','orders.progress','payments.manage','workers.manage','dashboard.view'], UserRole::Worker->value=>['orders.view','orders.progress','dashboard.view'], UserRole::Customer->value=>['orders.view','orders.create','wallet.withdraw','dashboard.view'], UserRole::Affiliate->value=>['affiliate.view','wallet.withdraw','dashboard.view']]; foreach($map as $roleName=>$rolePermissions){ Role::firstOrCreate(['name'=>$roleName,'guard_name'=>'web'])->syncPermissions($rolePermissions); } } }
